-- PostgreSQL: time-partitioned prediction log with indexed jsonb
CREATE TABLE prediction_log (
  id         bigint GENERATED ALWAYS AS IDENTITY,
  model_name text        NOT NULL,
  created_at timestamptz NOT NULL,
  payload    jsonb       NOT NULL
) PARTITION BY RANGE (created_at);

CREATE TABLE prediction_log_2026_01 PARTITION OF prediction_log
  FOR VALUES FROM ('2026-01-01') TO ('2026-02-01');

CREATE INDEX ON prediction_log (model_name, created_at);
CREATE INDEX ON prediction_log USING gin (payload);

-- pruned to one partition by the created_at filter
SELECT count(*) FROM prediction_log
WHERE model_name = 'ranker'
  AND created_at >= '2026-01-10' AND created_at < '2026-01-11';
